window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-883f838041ecec1c"]={"versions": [{"id": "FIG-883f838041ecec1c", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schematisches Datenstruktur- und Serialisierungsdiagramm (Byte-/Bit-Layout) im Kontext der AUTOSAR E2E-Library (End-to-End Communication Protection), spezifisch zur CRC-Berechnung eines E2E-Profils (Profil 1 / 11 / 21) bei Daten-Transformation oder Serialisierung im PDU-Layout.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind folgende Datenelemente und PDU-Felder:</p>\n<ul class=\"fig-list\">\n<li><code>Data Id</code>: Externe bzw. konfigurierte Daten-Identifikation zur Absicherung gegen Verwechslung von Kommunikationsbeziehungen.</li>\n<li><code>CRC</code>: Feld für die berechnete Prüfsumme (erstes Byte der Sequenz).</li>\n<li>Nibble-Aufteilung im zweiten Byte: Ein Nibble mit dem festen Maskierungs- bzw. Initialwert <code>0xF</code> und ein Nibble für den <code>Counter</code> (Alive-Counter / Sequenzzähler).</li>\n<li>Nutzdaten- und Padding-Felder: Segmente für <code>Sig 1</code> (Signal 1), ein unbeschriftetes Daten-/Lückenbyte, ein Padding-Byte mit dem Wert <code>0xFF</code> sowie ein erweitertes Datenfeld für <code>Sig 1</code>.</li>\n<li>Geschweifte Klammer (Berechnungsbereich) und Pfeilverbindung: Fasst die zu schützenden Nutzdaten- und Protokollbytes zusammen und führt diese gemeinsam mit der <code>Data Id</code> als Eingangsgrößen in die CRC-Berechnung ein, deren Ergebnis in das <code>CRC</code>-Feld geschrieben wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Schrittabfolge bei der Erstellung des abgesicherten Datensatzes (Schritt 4 des Schutzmechanismus) umfasst:</p>\n<ol class=\"fig-list\">\n<li>Zusammenstellung des Nutzdatenstroms einschließlich Counter-Nibble, statischer Füllwerte (<code>0xF</code>, <code>0xFF</code>) und Signaldaten (<code>Sig 1</code>).</li>\n<li>Zusammenführung der definierten Bytes/Nibbles aus dem Datenstrom (mittels geschweifter Klammer erfasst) mit der konfigurierten <code>Data Id</code>.</li>\n<li>Berechnung des resultierenden CRC-Werts über die kombinierten Eingangsdaten.</li>\n<li>Zuweisung und Eintragung des berechneten Prüfwerts in das dafür vorgesehene <code>CRC</code>-Byte am Beginn der PDU.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für die Implementierung der E2E-Schutzfunktion:</p>\n<ul class=\"fig-list\">\n<li>Die Prüfsummenberechnung erfordert exakte Byte- und Nibble-Positionierung gemäß Profilspezifikation; Nibble-Grenzen (<code>0xF</code> und <code>Counter</code> in einem Byte) müssen bitgenau beachtet werden.</li>\n<li>Die <code>Data Id</code> geht gemäß dem gezeigten Pfeilfluss direkt in die Prüfsummenbildung ein, wird jedoch nicht zwingend im übertragenen PDU-Payload mitgesendet (implizite Übertragung/Absicherung).</li>\n<li>Padding-Werte (z. B. <code>0xF</code>, <code>0xFF</code>) sind exakt wie vorgegeben zu initialisieren, um sender- und empfängerseitig identische CRC-Ergebnisse sicherzustellen.</li>\n</ul>"}, {"id": "FIG-5b5f357fae01eaa6", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schematisches Datenstruktur- und Serialisierungsdiagramm (Byte-/Bit-Layout) im Kontext der AUTOSAR E2E-Library (End-to-End Communication Protection), spezifisch zur CRC-Berechnung eines E2E-Profils (Profil 1 / 11 / 21) bei Daten-Transformation oder Serialisierung im PDU-Layout.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind folgende Datenelemente und PDU-Felder:</p>\n<ul class=\"fig-list\">\n<li><code>Data Id</code>: Externe bzw. konfigurierte Daten-Identifikation zur Absicherung gegen Verwechslung von Kommunikationsbeziehungen.</li>\n<li><code>CRC</code>: Feld für die berechnete Prüfsumme (erstes Byte der Sequenz).</li>\n<li>Nibble-Aufteilung im zweiten Byte: Ein Nibble mit dem festen Maskierungs- bzw. Initialwert <code>0xF</code> und ein Nibble für den <code>Counter</code> (Alive-Counter / Sequenzzähler).</li>\n<li>Nutzdaten- und Padding-Felder: Segmente für <code>Sig 1</code> (Signal 1), ein unbeschriftetes Daten-/Lückenbyte, ein Padding-Byte mit dem Wert <code>0xFF</code> sowie ein erweitertes Datenfeld für <code>Sig 1</code>.</li>\n<li>Geschweifte Klammer (Berechnungsbereich) und Pfeilverbindung: Fasst die zu schützenden Nutzdaten- und Protokollbytes zusammen und führt diese gemeinsam mit der <code>Data Id</code> als Eingangsgrößen in die CRC-Berechnung ein, deren Ergebnis in das <code>CRC</code>-Feld geschrieben wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Schrittabfolge bei der Erstellung des abgesicherten Datensatzes (Schritt 4 des Schutzmechanismus) umfasst:</p>\n<ol class=\"fig-list\">\n<li>Zusammenstellung des Nutzdatenstroms einschließlich Counter-Nibble, statischer Füllwerte (<code>0xF</code>, <code>0xFF</code>) und Signaldaten (<code>Sig 1</code>).</li>\n<li>Zusammenführung der definierten Bytes/Nibbles aus dem Datenstrom (mittels geschweifter Klammer erfasst) mit der konfigurierten <code>Data Id</code>.</li>\n<li>Berechnung des resultierenden CRC-Werts über die kombinierten Eingangsdaten.</li>\n<li>Zuweisung und Eintragung des berechneten Prüfwerts in das dafür vorgesehene <code>CRC</code>-Byte am Beginn der PDU.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für die Implementierung der E2E-Schutzfunktion:</p>\n<ul class=\"fig-list\">\n<li>Die Prüfsummenberechnung erfordert exakte Byte- und Nibble-Positionierung gemäß Profilspezifikation; Nibble-Grenzen (<code>0xF</code> und <code>Counter</code> in einem Byte) müssen bitgenau beachtet werden.</li>\n<li>Die <code>Data Id</code> geht gemäß dem gezeigten Pfeilfluss direkt in die Prüfsummenbildung ein, wird jedoch nicht zwingend im übertragenen PDU-Payload mitgesendet (implizite Übertragung/Absicherung).</li>\n<li>Padding-Werte (z. B. <code>0xF</code>, <code>0xFF</code>) sind exakt wie vorgegeben zu initialisieren, um sender- und empfängerseitig identische CRC-Ergebnisse sicherzustellen.</li>\n</ul>"}], "trans": [{"from": "FIG-883f838041ecec1c", "to": "FIG-5b5f357fae01eaa6", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
